function spreadZeros(grid: number[][]): void {
  const m = grid.length, n = grid[0].length;
  const rowZero = grid[0].some(v => v === 0);
  let colZero = false;
  for (let i = 0; i < m; i++) if (grid[i][0] === 0) colZero = true;
  for (let i = 1; i < m; i++)
    for (let j = 1; j < n; j++)
      if (grid[i][j] === 0) { grid[i][0] = 0; grid[0][j] = 0; }
  for (let i = 1; i < m; i++)
    for (let j = 1; j < n; j++)
      if (grid[i][0] === 0 || grid[0][j] === 0) grid[i][j] = 0;
  if (rowZero) for (let j = 0; j < n; j++) grid[0][j] = 0;
  if (colZero) for (let i = 0; i < m; i++) grid[i][0] = 0;
}

